{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "search_substr",
    "signature": "search_substr(fullText, searchText, allowOverlap=true)"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(fullText, str)",
