    {
      "id": "Q1",
      "expression": "return_value == 0 if searchText == '' else return_value >= 0",
      "description": "The return value is 0 if searchText is empty, otherwise it is non-negative"
    },
    {
      "id": "Q2",
      "expression": "return_value == sum(1 for i in range(len(fullText) - len(searchText) + 1) if fullText[i:i+len(searchText)] == searchText and (allowOverlap or i == 0 or fullText[i-1] != searchText[0]))",
      "description": "The return value is the number of times searchText appears in fullText, considering overlap if allowOverlap is true"
    }
  ],
  "invariants": []
}
